package com.kishku7.m1;

import net.minecraft.client.Minecraft;
import net.minecraft.world.item.crafting.Ingredient;

import java.util.List;

//[[[cog
//import sys; sys.path.insert(0, codegen); import compat
//]]]
//[[[end]]]

/**
 * Cog twin of RecipeCompat -- direct per-version recipe-book access for pre-26 Fabric (intermediary
 * runtime, where the reflection twin misses). 1.21.2+ casts the opaque handle to RecipeDisplayEntry;
 * pre-1.21.2 to RecipeHolder. Generated by Cog from _codegen/compat.py. Keep the surface identical to
 * the reflection twin at shared_minecraft/.../RecipeCompat.java. All version-specific types are fully
 * qualified so no version-gated imports are needed.
 */
public final class RecipeCompat {
    private RecipeCompat() {}

    public static List<Object> entries(Minecraft mc) {
        //[[[cog
        //for ln in compat.rc_entries(mcver): cog.outl(ln)
        //]]]
        java.util.List<Object> out = new java.util.ArrayList<>();
        for (net.minecraft.client.gui.screens.recipebook.RecipeCollection c : mc.player.getRecipeBook().getCollections()) {
            out.addAll(c.getRecipes());
        }
        return out;
        //[[[end]]]
    }

    public static String resultId(Minecraft mc, Object entry) {
        //[[[cog
        //for ln in compat.rc_result_id(mcver): cog.outl(ln)
        //]]]
        net.minecraft.world.item.ItemStack rr = ((net.minecraft.world.item.crafting.RecipeHolder<?>) entry).value().getResultItem(mc.level.registryAccess());
        if (rr.isEmpty()) { return ""; }
        return net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(rr.getItem()).toString();
        //[[[end]]]
    }

    public static boolean canCraft(Minecraft mc, Object entry) {
        //[[[cog
        //for ln in compat.rc_can_craft(mcver): cog.outl(ln)
        //]]]
        net.minecraft.world.entity.player.StackedContents sc = new net.minecraft.world.entity.player.StackedContents();
        mc.player.getInventory().fillStackedContents(sc);
        return sc.canCraft(((net.minecraft.world.item.crafting.RecipeHolder<?>) entry).value(), null);
        //[[[end]]]
    }

    public static List<Ingredient> requirements(Object entry) {
        //[[[cog
        //for ln in compat.rc_requirements(mcver): cog.outl(ln)
        //]]]
        java.util.List<net.minecraft.world.item.crafting.Ingredient> out = new java.util.ArrayList<>();
        out.addAll(((net.minecraft.world.item.crafting.RecipeHolder<?>) entry).value().getIngredients());
        return out;
        //[[[end]]]
    }

    @SuppressWarnings("deprecation")
    public static List<String> ingredientItemIds(Ingredient ing) {
        //[[[cog
        //for ln in compat.rc_ingredient_ids(mcver): cog.outl(ln)
        //]]]
        java.util.List<String> out = new java.util.ArrayList<>();
        for (net.minecraft.world.item.ItemStack st : ing.getItems()) { out.add(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(st.getItem()).toString()); }
        return out;
        //[[[end]]]
    }

    public static void placeRecipe(Minecraft mc, int containerId, Object entry, boolean shift) {
        //[[[cog
        //for ln in compat.rc_place(mcver): cog.outl(ln)
        //]]]
        mc.gameMode.handlePlaceRecipe(containerId, (net.minecraft.world.item.crafting.RecipeHolder<?>) entry, shift);
        //[[[end]]]
    }

    public static String label(Object entry) {
        //[[[cog
        //for ln in compat.rc_label(mcver): cog.outl(ln)
        //]]]
        return "recipe " + ((net.minecraft.world.item.crafting.RecipeHolder<?>) entry).id();
        //[[[end]]]
    }
}
